INSERT INTO `courses_quizquestion` VALUES (1,' What type of programming language is Python?','[\" Compiled and statically typed\", \"Interpreted and dynamically typed\", \" Low-level assembly language\", \"Markup language\"]','Interpreted and dynamically typed',248),(2,'. Which of the following IDEs is commonly used for Python development?','[\"MS Word\", \"PyCharm\", \"Photoshop\", \"After Effects\"]','PyCharm',248),(3,'What will be the output of this first Python program?  print(\"Hello, World!\"','[\"Hello World\", \"\\\"Hello, World!\\\"\", \"Hello, World!\", \"Error\"]','Hello, World!',248),(4,'In Python, how do you write a single-line comment','[\"comment\", \"//comment\", \"#comment\", \"* comment */\"]','#comment',248),(5,' Which of the following is true about Python','[\"Python was created by Guido van Rossum\", \" Python can only run on Windows.\", \" Python does not support comments\", \"Python is not object-oriented\"]','Python was created by Guido van Rossum',248);
